    /* ===== QUIZ-FILL PAGES -> PRACTICE EXERCISES =====
       Each shelf/reading's 'quiz-fill' page(s) hold the exact same
       fill-in-the-blank questions the Adventure Room's own lesson ends
       on (before/after/answer/altAnswers/hint) — reused as this Study
       Room's practice exercises rather than reinvented, same as every
       grammar-intro section above. */
    function buildExercisesFromPages(pages) {
        let exercises = [];
        pages.forEach(function (page) {
            if (page.type !== 'quiz-fill') return;
            (page.questions || []).forEach(function (q) {
                let accepted = [[q.answer]].concat((q.altAnswers || []).map(function (a) { return [a]; }));
                exercises.push({
                    prompt: "Fill in the blank: <span class='quizfill-context'>" + (q.before || "") + " <strong>_____</strong> " + (q.after || "") + "</span>",
                    accepted: accepted,
                    hint: q.hint || q.answer
                });
            });
        });
        return exercises;
    }

